<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{Support,Municipalities};
class CenterManagementController extends Controller {
 private function center(){abort_unless(auth()->user()->role==='sorting_center',403);$c=DB::table('sorting_centers')->where('user_id',auth()->id())->first();abort_unless($c,403);return $c;}
 private function courier(int $id,bool $lock=false){$c=$this->center();$q=DB::table('users')->where('id',$id)->where('role','rider')->where('company_id',auth()->id());$u=($lock?$q->lockForUpdate():$q)->first();abort_unless($u,404);abort_unless(Municipalities::matches($c,Municipalities::address($id)),403,'Courier must belong to your municipality.');return $u;}
 public function show(int $id){$u=$this->courier($id);return view('center_courier',['links'=>app(CommonController::class)->links(),'member'=>$u,'center'=>$this->center(),'address'=>Municipalities::address($id),'areas'=>DB::table('delivery_areas')->where('center_id',$this->center()->id)->where('rider_id',$id)->get(),'jobs'=>DB::table('assignments')->where('rider_id',$id)->select('status',DB::raw('COUNT(*) as total'))->groupBy('status')->pluck('total','status')]);}
 public function status(Request $r){$v=$r->validate(['id'=>'required|integer','active'=>'required|boolean','reason'=>'required|string|min:10|max:300']);DB::transaction(function()use($v){$u=$this->courier((int)$v['id'],true);abort_unless($u->approval_status==='approved',422,'Approve the application before managing account access.');$active=(bool)$v['active'];
 if(in_array($u->account_status,['banned','archived']))Support::fail('active','Only the logistics administrator can restore a banned or archived account.');
 if($active&&$u->account_status==='suspended'){$last=DB::table('audit_logs')->where('entity','user')->where('entity_id',$u->id)->whereIn('action',['account-status','center-courier-status'])->orderByDesc('id')->first();if(!$last||$last->action!=='center-courier-status'||$last->actor_id!=auth()->id())Support::fail('active','This suspension requires logistics administrator review.');}
 if(!$active&&(DB::table('assignments')->where('rider_id',$u->id)->where('status','accepted')->exists()||DB::table('driver_trips')->where('driver_id',$u->id)->whereIn('status',['accepted','in_transit'])->exists()))Support::fail('active','Finish accepted jobs before suspending this courier.');
 $state=$active?'active':'suspended';DB::table('users')->where('id',$u->id)->update(['active'=>$active,'account_status'=>$state,'account_status_reason'=>$v['reason'],'online'=>0,'api_token_expires_at'=>null,'remember_token'=>null,'updated_at'=>now()]);
 if(!$active){DB::table('assignments')->where('rider_id',$u->id)->where('status','offered')->whereNull('trip_id')->update(['status'=>'declined','updated_at'=>now()]);foreach(DB::table('driver_trips')->where('driver_id',$u->id)->where('status','offered')->pluck('id') as $trip)\App\Services\BulkTrips::close($trip,auth()->id(),'cancelled');}
 if($active)DB::table('courier_appeals')->where('user_id',$u->id)->where('status','pending')->update(['status'=>'approved','reviewed_by'=>auth()->id(),'review_reason'=>$v['reason'],'updated_at'=>now()]);
 Support::audit('center-courier-status','user',$u->id,$u,['account_status'=>$state],$v['reason']);Support::notify([$u->id],'Your account is '.$state.': '.$v['reason']);});return back()->with('success','Courier account updated.');}
 public function area(Request $r,int $id){$c=$this->center();$v=$r->validate(['action'=>'required|in:assign,delete','rider_id'=>'required_if:action,assign|nullable|integer']);DB::transaction(function()use($c,$id,$v){$a=DB::table('delivery_areas')->where('id',$id)->where('center_id',$c->id)->lockForUpdate()->first();abort_unless($a,404);
 if($v['action']==='assign'){$u=$this->courier((int)$v['rider_id'],true);abort_unless($u->courier_type==='rider'&&$u->active&&$u->account_status==='active'&&$u->approval_status==='approved',422);DB::table('delivery_areas')->where('id',$id)->update(['rider_id'=>$u->id,'updated_at'=>now()]);}
 else {if(DB::table('parcels')->where('delivery_area_id',$id)->whereNotIn('status',['DELIVERED','COMPLETED','RETURNED','RETURN_RECEIVED','CANCELLED'])->exists())Support::fail('area','Finish active parcels in this area before deleting it.');DB::table('parcels')->where('delivery_area_id',$id)->update(['delivery_area_id'=>null]);DB::table('delivery_areas')->where('id',$id)->delete();}Support::audit('area-'.$v['action'],'delivery_area',$id,$a,$v);});return back()->with('success','Area updated. Existing assignments keep their assigned rider.');}
 public function appeals(){ $c=$this->center();$rows=DB::table('courier_appeals as a')->join('users as u','u.id','=','a.user_id')->where('u.company_id',auth()->id())->where('u.role','rider')->orderByDesc('a.id')->select('a.*','u.name','u.courier_type','u.account_status')->get()->filter(fn($a)=>Municipalities::matches($c,Municipalities::address($a->user_id)));return view('center_appeals',['links'=>app(CommonController::class)->links(),'appeals'=>\App\Services\ProcessRouting::paginate($rows->values())]);}
 public function review(Request $r,int $id){$v=$r->validate(['decision'=>'required|in:approved,rejected','reason'=>'required|string|min:10|max:300']);$a=DB::table('courier_appeals')->find($id);abort_unless($a,404);abort_unless($a->status==='pending',422,'This appeal was already reviewed.');$this->courier($a->user_id);if($v['decision']==='approved'){$r->merge(['id'=>$a->user_id,'active'=>1]);return $this->status($r);}DB::transaction(function()use($id,$v){$a=DB::table('courier_appeals')->where('id',$id)->lockForUpdate()->first();abort_unless($a&&$a->status==='pending',422);$this->courier($a->user_id,true);DB::table('courier_appeals')->where('id',$id)->update(['status'=>'rejected','reviewed_by'=>auth()->id(),'review_reason'=>$v['reason'],'updated_at'=>now()]);Support::audit('courier-appeal-rejected','courier_appeal',$id,$a,$v);});return back()->with('success','Appeal reviewed.');}
 public function appealForm(){abort_unless(auth()->user()->role==='rider'&&auth()->user()->account_status==='suspended',403);return view('courier_appeal_form',['appeals'=>DB::table('courier_appeals')->where('user_id',auth()->id())->orderByDesc('id')->get()]);}
 public function submitAppeal(Request $r){$v=$r->validate(['message'=>'required|string|min:20|max:2000']);DB::transaction(function()use($v){$u=DB::table('users')->where('id',auth()->id())->lockForUpdate()->first();abort_unless($u->role==='rider'&&$u->account_status==='suspended'&&$u->company_id,403);if(DB::table('courier_appeals')->where('user_id',$u->id)->where('status','pending')->exists())Support::fail('message','You already have a pending appeal.');DB::table('courier_appeals')->insert($v+['user_id'=>$u->id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);Support::notify([$u->company_id],'A courier submitted a suspension appeal. Open Appeal to review.');});return back()->with('success','Appeal submitted to your sorting center.');}
}
